<?php
require_once __DIR__ . '/../includes/auth.php'; require_role(['admin']);
$stmt = $pdo->query("SELECT p.id, p.reason, p.details, p.status, p.created_at, r.id AS resource_id, r.title, c.id AS comment_id, c.body AS comment_body, u.full_name AS reporter FROM reports p JOIN users u ON u.id = p.reporter_id LEFT JOIN resources r ON r.id = p.resource_id LEFT JOIN comments c ON c.id = p.comment_id WHERE p.status = 'open' ORDER BY p.created_at ASC"); $reports = $stmt->fetchAll(); $page_title = 'Reports'; require __DIR__ . '/../includes/header.php';
?>
<div class="page-header"><div><h1>Reports</h1><p class="muted"><?= count($reports) ?> open reports awaiting review.</p></div></div><?php if (!$reports): ?><div class="empty-state">No open reports.</div><?php else: ?><div class="table-wrap"><table class="table"><thead><tr><th>Reported item</th><th>Reason</th><th>Reporter</th><th>Details</th><th>Actions</th></tr></thead><tbody><?php foreach ($reports as $report): ?><tr><td><?php if ($report['resource_id']): ?><a href="<?= e(url('resource_details.php?id=' . $report['resource_id'])) ?>"><?= e($report['title']) ?></a><?php else: ?>Comment: <?= e(str_limit($report['comment_body'], 100)) ?><?php endif; ?></td><td><?= e(REPORT_REASONS[$report['reason']] ?? $report['reason']) ?></td><td><?= e($report['reporter']) ?><br><span class="muted"><?= e(format_date($report['created_at'])) ?></span></td><td><?= e($report['details'] ?: 'None') ?></td><td class="table-actions"><form method="post" action="<?= e(url('actions/admin/resolve_report.php')) ?>" class="inline-form"><?= csrf_field() ?><input type="hidden" name="report_id" value="<?= (int) $report['id'] ?>"><input type="hidden" name="decision" value="upheld"><button class="btn btn-sm btn-danger" type="submit">Uphold</button></form><form method="post" action="<?= e(url('actions/admin/resolve_report.php')) ?>" class="inline-form"><?= csrf_field() ?><input type="hidden" name="report_id" value="<?= (int) $report['id'] ?>"><input type="hidden" name="decision" value="dismissed"><button class="btn btn-sm" type="submit">Dismiss</button></form></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?>
<?php require __DIR__ . '/../includes/footer.php'; ?>
